using System;
using System.Collections.Generic;
using UnityEngine;

namespace LassylaPort
{
    // Read-only meshes can keep their original vertex layout. Their rest coordinates live
    // in a shared vertex-indexed texture generated by the editor importer.
    public sealed class LassylaMeshCoordinates : ScriptableObject
    {
        [Serializable] public struct Entry { public Mesh mesh; public int offset; }
        public Entry[] entries;
        public Texture2D table;
        readonly Dictionary<Mesh,int> offsets=new();
        readonly Dictionary<Renderer,Mesh> bound=new();
        readonly List<Material> materials=new();
        readonly List<Renderer> expired=new();
        MaterialPropertyBlock block;
        static readonly int First=Shader.PropertyToID("_ToonCoordFirst"),Table=Shader.PropertyToID("_ToonCoordTable");
        static readonly int Enabled=Shader.PropertyToID("_LassylaEdgeEnabled");

        void OnEnable(){offsets.Clear();bound.Clear();}

        public int BindVisibleMaterials()
        {
            int layers=0;
            if(offsets.Count==0 && entries!=null)foreach(var entry in entries)if(entry.mesh)offsets[entry.mesh]=entry.offset+1;
            block??=new MaterialPropertyBlock();
            // Discover new instances and mesh swaps as well as material toggles made by scripts.
            // Only registered meshes with an enabled material acquire a property block.
            foreach(var r in FindObjectsByType<Renderer>(FindObjectsSortMode.None)){
                Mesh mesh=r is SkinnedMeshRenderer skin?skin.sharedMesh:
                    r is MeshRenderer && r.TryGetComponent<MeshFilter>(out var f)?f.sharedMesh:null;
                r.GetSharedMaterials(materials);
                bool enabled=false;
                foreach(var m in materials)if(m && m.HasProperty(Enabled) && m.GetFloat(Enabled)>.5f){enabled=true;break;}
                if(enabled && r.enabled)layers|=1<<r.gameObject.layer;
                if(!mesh || !offsets.TryGetValue(mesh,out var first)){
                    if(bound.Remove(r))Bind(r,0);
                    continue;
                }
                if(enabled){Bind(r,first);bound[r]=mesh;}
                else if(bound.Remove(r))Bind(r,0);
            }
            materials.Clear();
            expired.Clear();foreach(var pair in bound)if(!pair.Key)expired.Add(pair.Key);
            foreach(var dead in expired)bound.Remove(dead);
            return layers;
        }

        void Bind(Renderer renderer,int first)
        {
            renderer.GetPropertyBlock(block);
            if(UpdateBlock(first))renderer.SetPropertyBlock(block);
            // A per-slot block takes precedence over the renderer-wide block in Unity.
            if(first==0)renderer.GetSharedMaterials(materials);
            for(int i=0;i<materials.Count;i++){
                renderer.GetPropertyBlock(block,i);
                if(!block.isEmpty && UpdateBlock(first))renderer.SetPropertyBlock(block,i);
            }
        }

        bool UpdateBlock(int first)
        {
            if(block.GetFloat(First)==first && (first==0 || block.GetTexture(Table)==table))return false;
            block.SetFloat(First,first);
            if(first!=0)block.SetTexture(Table,table);
            return true;
        }
    }
}
